// marshalExploreExploreQueryToExploreQueryResponseBody builds a value of type
// *ExploreQueryResponseBody from a value of type *explore.ExploreQuery.
func marshalExploreExploreQueryToExploreQueryResponseBody(v *explore.ExploreQuery) *ExploreQueryResponseBody {
	res := &ExploreQueryResponseBody{
		ID:              v.ID,
		ProjectID:       v.ProjectID,
		OrganizationID:  v.OrganizationID,
		CreatedByUserID: v.CreatedByUserID,
		Name:            v.Name,
		Dataset:         v.Dataset,
		InvalidReason:   v.InvalidReason,
		CreatedAt:       v.CreatedAt,
		UpdatedAt:       v.UpdatedAt,
	}
	if v.Spec != nil {
		res.Spec = make(map[string]any, len(v.Spec))
		for key, val := range v.Spec {
			tk := key
			tv := val
			res.Spec[tk] = tv
		}
	}

	return res
}
